    enonce: "<span dir=\"ltr\" class=\"expr\">ABC</span> مثلّث قائم الزاوية في <span dir=\"ltr\" class=\"expr pt\">B</span> حيث <span dir=\"ltr\" class=\"expr\">AB = 3</span> و <span dir=\"ltr\" class=\"expr\">BC = 4.</span><br><svg class=\"figure\" direction=\"ltr\" viewBox=\"0 0 332 244\" width=\"332\" height=\"244\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"63.5\" y1=\"63.5\" x2=\"112.2\" y2=\"180.5\" stroke=\"#2c3e50\" stroke-width=\"1.8\"/><line x1=\"112.2\" y1=\"180.5\" x2=\"268.3\" y2=\"115.5\" stroke=\"#2c3e50\" stroke-width=\"1.8\"/><line x1=\"63.5\" y1=\"63.5\" x2=\"268.3\" y2=\"115.5\" stroke=\"#2c3e50\" stroke-width=\"1.8\"/><line x1=\"63.5\" y1=\"63.5\" x2=\"112.2\" y2=\"180.5\" stroke=\"#2c3e50\" stroke-width=\"1.8\"/><path d=\"M 108.0 170.4 L 118.2 166.1 L 122.4 176.3\" fill=\"none\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><path d=\"M 108.0 170.4 L 108.0 170.4 L 112.2 180.5\" fill=\"none\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><circle cx=\"112.2\" cy=\"180.5\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"105.6\" y=\"195.7\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">B</text><circle cx=\"63.5\" cy=\"63.5\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"52.7\" y=\"60.3\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">A</text><circle cx=\"268.3\" cy=\"115.5\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"281.3\" y=\"119.0\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">C</text></svg><br>أحسب بعد <span dir=\"ltr\" class=\"expr pt\">A</span> عن <span dir=\"ltr\" class=\"expr\">(BC).</span>",
    correction: [{"quoi":"المسقط العمودي","math":"<span dir=\"ltr\" class=\"expr pt\">B</span> هو المسقط العمودي لـ <span dir=\"ltr\" class=\"expr pt\">A</span> على <span dir=\"ltr\" class=\"expr\">(BC)</span>"},{"quoi":"القاعدة","math":"بعد نقطة عن مستقيم هو طول القطعة التي تصلها بمسقطها العمودي عليه"},{"quoi":"نقرأ الطول","math":"<span dir=\"ltr\" class=\"expr\">AB = 3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">d(A</span> ، <span dir=\"ltr\" class=\"expr\">(BC)) = 3</span> صم"}],
